package com.wedo.backend.activity.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
import com.wedo.backend.activity.entity.*; import com.wedo.backend.activity.repository.ActivityRepository; import com.wedo.backend.group.service.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class M8ActivityAccessServiceTest { @Test void readableAccessUsesActivityGroupMembershipRatherThanParticipantState(){ActivityRepository activities=mock(ActivityRepository.class);GroupPermissionService groups=mock(GroupPermissionService.class);UUID activityId=UUID.randomUUID(),groupId=UUID.randomUUID(),actor=UUID.randomUUID();ActivityEntity activity=new ActivityEntity(activityId,groupId,actor,"A",null,ActivityStatus.CONFIRMED,null,null,null,null,null,Instant.EPOCH,Instant.EPOCH);when(activities.findById(activityId)).thenReturn(Optional.of(activity));when(groups.requireReadableMembership(groupId,actor)).thenReturn(mock(ReadableGroupAccess.class));M8ActivityAccessService service=new M8ActivityAccessService(activities,groups);assertEquals(activity,service.requireReadable(activityId,actor).activity());verify(groups).requireReadableMembership(groupId,actor);}}
